// core-sync: 1.0.0 — mirrors evaluateSendGuards/buildIdempotencyKey/withinMessagingHours/validateOutboundContent in scripts/lib/agent-core.mjs.
const inp = $('When Executed by Another Workflow').first().json;
const cfgRows = (() => { try { return $('Read Kill Switches + Limits').all().map(i => i.json).filter(r => r.key); } catch (e) { return []; } })();
const cfg = {}; cfgRows.forEach(r => { cfg[r.key] = r.value; });
const compliance = JSON.parse($env.COMPLIANCE_RULES_JSON || '{}');
const hours = { timezone: $env.MESSAGING_TIMEZONE || 'America/New_York', start: $env.MESSAGING_HOURS_START || '09:00', end: $env.MESSAGING_HOURS_END || '20:00', days: ['Mon','Tue','Wed','Thu','Fri','Sat'] };
// --- fresh record state (fail closed on unknown for proactive sends) ---
let rec = null;
try { const q = $('Salesforce: Fresh Record State').first().json; rec = (q.records || [])[0] || null; } catch (e) { rec = null; }
if (!rec && inp.record_state_json) { try { rec = JSON.parse(inp.record_state_json); } catch {} }
const map = JSON.parse($env.SF_FIELD_MAP_JSON || '{}');
const m = map.mappings || {};
const obj = (inp.record_ref || 'Lead:').split(':')[0];
const fval = (k) => { const s = m[k]; if (!s || s.field === 'UNMAPPED' || s.object !== obj || !rec) return undefined; return rec[s.field]; };
const isReply = inp.is_reply_to_inbound === true;
const consentMapped = m.sms_consent && m.sms_consent.field !== 'UNMAPPED';
// Consent: replies to an inbound message are permitted responses; proactive sends require mapped consent=true.
const consent_ok = isReply ? true : (consentMapped ? String(fval('sms_consent')) === 'true' : false);
// Customer replied since scheduled (scheduled/proactive sends only)
let repliedSince = false;
if (inp.scheduled_at) { const li = fval('last_inbound_date'); if (li && new Date(li) > new Date(inp.scheduled_at)) repliedSince = true; }
// Messaging hours
function withinHours(nowISO, h) { const now = new Date(nowISO); const fmt = new Intl.DateTimeFormat('en-US', { timeZone: h.timezone, hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit' }); const parts = Object.fromEntries(fmt.formatToParts(now).map(p => [p.type, p.value])); const hm = `${parts.hour === '24' ? '00' : parts.hour}:${parts.minute}`; if (h.days && !h.days.includes(parts.weekday)) return false; return hm >= h.start && hm < h.end; }
// Rate limit: count idempotency rows created in the last 60s
let recentCount = 0;
try { const rows = $('Count Recent Outbound (Rate Limit)').all().map(i => i.json); const cutoff = Date.now() - 60000; recentCount = rows.filter(r => r.created_at && new Date(r.created_at).getTime() > cutoff && r.accepted_by_sendblue).length; } catch (e) { recentCount = 0; }
const rateLimit = Number(cfg.rate_limit_per_minute || 20);
// Content compliance (defense in depth even when pre-validated upstream)
function contentOk(content, templateId) { const v = compliance.outbound_validation || {}; const t = String(content || ''); if (!t.trim()) return false; if (v.max_message_length && t.length > v.max_message_length) return false; if (templateId && (v.whitelisted_template_ids || []).includes(templateId)) return true; for (const p of v.forbidden_content_patterns || []) { try { if (new RegExp(p, 'i').test(t)) return false; } catch {} } return true; }
// Idempotency key
function key(correlationId, to, content) { let h = 5381; const s = `${to}|${content}`; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return `out_${correlationId}_${h.toString(16)}`; }
const idempotency_key = key(inp.correlation_id, inp.to_number, inp.content || '');
const test_allowlist = String(cfg.test_allowlist_numbers || '').split(',').map(s => s.trim()).filter(Boolean);
const ctx = {
  global_ai_enabled: cfg.global_ai_enabled === 'true',
  outbound_enabled: cfg.outbound_enabled === 'true',
  record_ai_enabled: fval('ai_enabled') === undefined ? undefined : String(fval('ai_enabled')) === 'true',
  human_takeover: String(fval('human_takeover')) === 'true',
  opted_out: String(fval('sms_opt_out')) === 'true',
  suppressed: false,
  wrong_number: String(fval('wrong_number')) === 'true',
  consent_ok,
  content: inp.content,
  compliance_passed: contentOk(inp.content, inp.template_id),
  idempotency_key_fresh: true,
  to_number: inp.to_number,
  from_number: $env.SENDBLUE_FROM_NUMBER,
  is_reply_to_inbound: isReply,
  within_messaging_hours: withinHours(new Date().toISOString(), hours),
  rate_limit_ok: recentCount < rateLimit,
  customer_replied_since_scheduled: repliedSince,
  test_mode: cfg.test_mode !== 'false',
  allow_real_send: $env.ALLOW_REAL_SEND === 'true',
  test_allowlist
};
function evaluateSendGuards(c) { const failures = []; const g = (cond, code) => { if (!cond) failures.push(code); };
  g(c.global_ai_enabled === true, 'global_ai_disabled'); g(c.outbound_enabled === true, 'outbound_disabled');
  g(c.record_ai_enabled !== false, 'record_ai_disabled'); g(c.human_takeover !== true, 'human_takeover_active');
  g(c.opted_out !== true, 'opted_out'); g(c.suppressed !== true, 'suppressed'); g(c.wrong_number !== true, 'wrong_number');
  g(c.consent_ok === true, 'consent_missing'); g(typeof c.content === 'string' && c.content.trim().length > 0, 'blank_message');
  g(c.compliance_passed === true, 'compliance_failed'); g(c.idempotency_key_fresh === true, 'duplicate_idempotency_key');
  g(!!c.to_number && !!c.from_number && c.to_number !== c.from_number, 'invalid_endpoints');
  g(c.is_reply_to_inbound === true || c.within_messaging_hours === true, 'outside_messaging_hours');
  g(c.rate_limit_ok === true, 'rate_limited'); g(c.customer_replied_since_scheduled !== true, 'customer_replied_since_scheduled');
  let mode = 'real';
  if (c.test_mode === true) { mode = (c.test_allowlist || []).includes(c.to_number) ? 'test_allowlisted' : 'mock'; }
  else { g(c.allow_real_send === true, 'real_send_not_enabled'); }
  return { allowed: failures.length === 0, failures, mode }; }
const verdict = evaluateSendGuards(ctx);
console.log(JSON.stringify({ level: verdict.allowed ? 'info' : 'warn', workflow: 'SB-06', workflow_version: '1.0.0', correlation_id: inp.correlation_id, action: 'guard_evaluation', allowed: verdict.allowed, mode: verdict.mode, failures: verdict.failures, record_ref: inp.record_ref || null, ts: new Date().toISOString() }));
return [{ json: { ...inp, idempotency_key, verdict, send_mode: verdict.mode, seat_id: $env.SENDBLUE_EMMA_SEAT_ID || null, seat_param: $env.SENDBLUE_SEAT_PARAM || 'seat_id' } }];

const j = $('Evaluate All Send Guards').first().json;
console.log(JSON.stringify({ level: 'warn', workflow: 'SB-06', correlation_id: j.correlation_id, action: 'duplicate_send_suppressed', idempotency_key: j.idempotency_key, ts: new Date().toISOString() }));
return [{ json: { sent: false, duplicate: true, correlation_id: j.correlation_id } }];

// test_mode + recipient not on test_allowlist => never touches Sendblue.
const j = $('Evaluate All Send Guards').first().json;
console.log(JSON.stringify({ level: 'info', workflow: 'SB-06', correlation_id: j.correlation_id, action: 'mock_send', template_id: j.template_id || null, record_ref: j.record_ref || null, content_length: (j.content || '').length, ts: new Date().toISOString() }));
return [{ json: { status: 'MOCKED', message_handle: 'mock_' + j.idempotency_key, mocked: true } }];
